<?php
require_once __DIR__.'/_layout.php';
requirePermission('inspections.manage');
if(requestMethod()==='POST'){
    requireCsrfPost();
    $action='';
    try {
        $action=(string)($_POST['action']??'');if($action==='rental_checkout'&&!can('rental.checkout')){http_response_code(403);exit(t('validation.not_authorized'));}if($action==='rental_checkin'&&!can('rental.checkin')){http_response_code(403);exit(t('validation.not_authorized'));}
        if($action==='photo_bundle'){
            $rawInspectionId=$_POST['inspection_id']??null;if(!is_string($rawInspectionId)||!preg_match('/^[1-9]\d*$/',$rawInspectionId))throw new InvalidArgumentException(t('validation.inspection_photo_not_found'));$inspectionId=(int)$rawInspectionId;$raw=$_FILES['photos']??[];$expectedUploadFields=['name','type','tmp_name','error','size'];$allowedUploadFields=[...$expectedUploadFields,'full_path'];if(!is_array($raw)||array_diff(array_keys($raw),$allowedUploadFields)||array_diff($expectedUploadFields,array_keys($raw)))throw new InvalidArgumentException(t('validation.inspection_photo_bundle'));foreach($expectedUploadFields as$field)if(!is_array($raw[$field])||array_keys($raw[$field])!==inspectionPhotoSlots())throw new InvalidArgumentException(t('validation.inspection_photo_bundle'));$uploads=[];
            foreach(inspectionPhotoSlots() as $slot)$uploads[$slot]=['name'=>$raw['name'][$slot]??null,'type'=>$raw['type'][$slot]??null,'tmp_name'=>$raw['tmp_name'][$slot]??null,'error'=>$raw['error'][$slot]??UPLOAD_ERR_NO_FILE,'size'=>$raw['size'][$slot]??0];
            $staged=inspectionPhotoStageBundle($uploads);inspectionPhotoPersistBundle($inspectionId,$staged,(string)($_POST['idempotency_key']??''));flash('success',t('message.inspection_photo_bundle_stored'));
        } elseif($action==='rental_checkout') {
            $rawId=$_POST['inspection_id']??null;if(!is_string($rawId)||!preg_match('/^[1-9]\d*$/',$rawId))throw new InvalidArgumentException(t('validation.checkout_not_found'));$inspection=inspectionPhotoScopedInspection((int)$rawId);if(!$inspection)throw new InvalidArgumentException(t('validation.checkout_not_found'));
            if(PHP_SAPI==='cli'&&defined('RENTAL_CHECKOUT_CONTROLLER_TEST_HOOK')&&RENTAL_CHECKOUT_CONTROLLER_TEST_HOOK===true&&function_exists('rentalCheckoutControllerTestHook'))rentalCheckoutControllerTestHook();
            rentalCheckout(['reservation_id'=>(int)$inspection['reservation_id'],'contract_id'=>(int)$inspection['contract_id'],'inspection_id'=>(int)$inspection['id'],'idempotency_key'=>(string)($_POST['idempotency_key']??''),'mileage'=>$_POST['mileage']??null,'fuel_level'=>$_POST['fuel_level']??null,'handed_over_at'=>$_POST['handed_over_at']??null,'comment'=>$_POST['comment']??null]);flash('success',t('message.rental_checkout_completed'));
        } elseif($action==='rental_checkin') {
            $rawId=$_POST['inspection_id']??null;if(!is_string($rawId)||!preg_match('/^[1-9]\d*$/',$rawId))throw new InvalidArgumentException(t('validation.checkin_not_found'));$inspection=inspectionPhotoScopedInspection((int)$rawId);if(!$inspection)throw new InvalidArgumentException(t('validation.checkin_not_found'));
            if(PHP_SAPI==='cli'&&defined('RENTAL_CHECKIN_CONTROLLER_TEST_HOOK')&&RENTAL_CHECKIN_CONTROLLER_TEST_HOOK===true&&function_exists('rentalCheckinControllerTestHook'))rentalCheckinControllerTestHook();
            rentalCheckin(['reservation_id'=>(int)$inspection['reservation_id'],'contract_id'=>(int)$inspection['contract_id'],'inspection_id'=>(int)$inspection['id'],'idempotency_key'=>(string)($_POST['idempotency_key']??''),'mileage'=>$_POST['mileage']??null,'fuel_level'=>$_POST['fuel_level']??null,'returned_at'=>$_POST['returned_at']??null,'vehicle_condition'=>$_POST['vehicle_condition']??null,'comment'=>$_POST['comment']??null]);flash('success',t('message.rental_checkin_completed'));
        } elseif($action==='photo_archive') {
            $rawPhotoId=$_POST['photo_id']??null;if(!is_string($rawPhotoId)||!preg_match('/^[1-9]\d*$/',$rawPhotoId))throw new InvalidArgumentException(t('validation.inspection_photo_not_found'));inspectionPhotoArchive((int)$rawPhotoId,(string)($_POST['reason']??''));flash('success',t('message.inspection_photo_archived'));
        } else throw new DomainException(t('validation.inspection_cutover_read_only'));
    } catch(Throwable $e) { if($e instanceof AuthorizationException)flash('danger',t('validation.not_authorized'));elseif($e instanceof InvalidArgumentException||$e instanceof DomainException)flash('danger',$e->getMessage());elseif($action==='rental_checkin'){error_log('Phase 5B.4 check-in/controller failure: '.get_class($e));flash('danger',t('validation.checkin_failed'));}else{error_log('Phase 5B.3 checkout/controller failure: '.get_class($e));flash('danger',t('validation.checkout_failed'));} }
    safeRedirect('inspections.php');
}
$agencyIds=currentAgencyIds();if(!$agencyIds)$agencyIds=[0];$ph=implode(',',array_fill(0,count($agencyIds),'?'));
$inspections=tableExists('contract_status_history')?dbFetchAll(
    "SELECT vi.*,rc.contract_number,rc.status contract_status,rc.current_version, v.registration_number,v.status vehicle_status,c.first_name,c.last_name,r.reference reservation_reference,r.status reservation_status,r.pickup_at,r.return_at,
            (SELECT ci.completed_at FROM vehicle_inspections ci WHERE ci.agency_id=vi.agency_id AND ci.contract_id=vi.contract_id AND ci.inspection_type='checkout' AND ci.status='completed' AND ci.archived_at IS NULL LIMIT 1) checkout_at,
            (SELECT ci.mileage FROM vehicle_inspections ci WHERE ci.agency_id=vi.agency_id AND ci.contract_id=vi.contract_id AND ci.inspection_type='checkout' AND ci.status='completed' AND ci.archived_at IS NULL LIMIT 1) checkout_mileage,
            (SELECT COUNT(*) FROM inspection_photos ip WHERE ip.inspection_id=vi.id AND ip.agency_id=vi.agency_id AND ip.archived_at IS NULL) photo_count,
            (SELECT COUNT(*) FROM vehicle_damages vd WHERE vd.inspection_id=vi.id) damage_case_count,
            (SELECT COUNT(*)=6
                    AND SUM(ip.photo_slot='front')=1 AND SUM(ip.photo_slot='rear')=1
                    AND SUM(ip.photo_slot='left')=1 AND SUM(ip.photo_slot='right')=1
                    AND SUM(ip.photo_slot='interior')=1 AND SUM(ip.photo_slot='dashboard')=1
             FROM inspection_photos ip
             WHERE ip.inspection_id=vi.id AND ip.agency_id=vi.agency_id AND ip.archived_at IS NULL) photo_bundle_complete,
            ((SELECT COUNT(*) FROM contract_acknowledgements ca WHERE ca.contract_id=rc.id AND ca.contract_version_id=rc.current_version_id)=2
             AND (SELECT COUNT(DISTINCT ca.acknowledgement_type) FROM contract_acknowledgements ca WHERE ca.contract_id=rc.id AND ca.contract_version_id=rc.current_version_id)=2) acknowledgements_complete
     FROM vehicle_inspections vi
     JOIN rental_contracts rc ON rc.id=vi.contract_id AND rc.agency_id=vi.agency_id
     JOIN reservations r ON r.id=vi.reservation_id AND r.agency_id=vi.agency_id
     JOIN vehicles v ON v.id=vi.vehicle_id AND v.agency_id=vi.agency_id
     JOIN customers c ON c.id=vi.customer_id AND c.agency_id=vi.agency_id
     WHERE vi.agency_id IN ($ph) ORDER BY vi.inspected_at DESC LIMIT 100",
    $agencyIds
):[];
$photosByInspection=[];if($inspections&&can('inspection_photos.view')){foreach(dbFetchAll("SELECT id,inspection_id,photo_slot,archived_at FROM inspection_photos WHERE inspection_id IN (".implode(',',array_fill(0,count($inspections),'?')).") ORDER BY photo_slot,id",array_column($inspections,'id')) as $photo)$photosByInspection[(int)$photo['inspection_id']][]=$photo;}
backofficeHeader(t('page.inspections.title'),'inspections.php');
pageHeader('page.inspections.title','page.inspections.description',['breadcrumbs'=>[['label'=>'nav.rentals'],['label'=>'nav.inspections']]]);
